def solve_equal_three(text):
    tokens = text.split()
    n = int(tokens[0])
    calls = tokens[1] if n else ""
    seen = {(0, 0): 1}
    a = b = c = 0
    total = 0
    for ch in calls:
        if ch == "A":
            a += 1
        elif ch == "B":
            b += 1
        else:
            c += 1
        key = (a - b, b - c)
        total += seen.get(key, 0)
        seen[key] = seen.get(key, 0) + 1
    return str(total)

